function mergeFeeds(a, b) {
  const out = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i][0] <= b[j][0]) out.push(a[i++]);   // <= keeps ties in a's favour
    else out.push(b[j++]);
  }
  // Exactly one of these two still has records in it.
  while (i < a.length) out.push(a[i++]);
  while (j < b.length) out.push(b[j++]);
  return out;
}
